        float4 xstreak() {
            float texelSize = 1.0 / screen.zw.x;
            float dist = amzp_strength * 0.05;
            int nSamples = int(clamp(dist/texelSize,1.01,100.01));
            float4 c = float4(0.);
            for( int i=1; i<nSamples; i++ ) {
                float offset = dist * (float(i)/float(nSamples-1) - 0.5);
                float2 sampleCoord = amzScreenNorm() + float2(offset,0.);
                float4 tc = sampleTex(sampleCoord);
                if( offset < 0. ) {
                    c = c * (1.-tc.a) + tc;
                } else {
                    c = tc * (1.-c.a) + c;
                }
            }
            return c;
        }

        float4 ystreak() {
            float texelSize = 1.0 / screen.zw.y;
            float dist = amzp_strength * 0.05;
            int nSamples = int(clamp(dist/texelSize,1.01,100.01));
            float4 c = float4(0.);
            for( int i=1; i<nSamples; i++ ) {
                float offset = dist * (float(i)/float(nSamples-1) - 0.5);
                float2 sampleCoord = amzScreenNorm() + float2(0.,offset);
                float4 tc = sampleTex(sampleCoord);
                if( offset < 0. ) {
                    c = c * (1.-tc.a) + tc;
