        );

        void amzRender() {
            if( amzPass==1 || amzPass==2 ) {
                float4 c1 = xstreak();
                float4 c2 = ystreak();
                float4 blur = amzTexture(1, amzScreenNorm());
                amzOutput = composite(composite(c1,c2),blur);
            } else {
                float4 base = amzTexture(0, amzScreenNorm());
                float4 blur = amzTexture(1, amzScreenNorm());
                float4 streak = amzTexture(3, amzScreenNorm());
                float4 c = streak * saturate((1.-blur.a)*2.) * base.a;
                float3 baseYUV = (base.rgb/max(0.00001,base.a)) * rgb2yuv;
                float3 cYUV = (c.rgb/max(0.00001,c.a)) * rgb2yuv;
                cYUV.x = baseYUV.x;
                c = float4(cYUV * yuv2rgb,1.) * c.a;
                amzOutput = composite(base,c);
            }
        }


